CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_panel]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_panel]
	(
		[apuk_assessmentevent],
		[apuk_assessmentevent_entitytype],
		[apuk_assessmenteventname],
		[apuk_assessmentvenue],
		[apuk_assessmentvenue_entitytype],
		[apuk_assessmentvenuename],
		[apuk_date],
		[apuk_name],
		[apuk_panelid],
		[apuk_paneltype],
		[apuk_tribunalchair],
		[apuk_tribunalchair_entitytype],
		[apuk_tribunalchairname],
		[apuk_tribunalchairyominame],
		[apuk_tribunallaymember],
		[apuk_tribunallaymember_entitytype],
		[apuk_tribunallaymembername],
		[apuk_tribunallaymemberyominame],
		[apuk_tribunallegalassessor],
		[apuk_tribunallegalassessor_entitytype],
		[apuk_tribunallegalassessorname],
		[apuk_tribunallegalassessoryominame],
		[apuk_tribunalmember],
		[apuk_tribunalmember_entitytype],
		[apuk_tribunalmembername],
		[apuk_tribunalmemberyominame],
		[apuk_tribunalvenue],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_assessmentevent],
		stg.[apuk_assessmentevent_entitytype],
		stg.[apuk_assessmenteventname],
		stg.[apuk_assessmentvenue],
		stg.[apuk_assessmentvenue_entitytype],
		stg.[apuk_assessmentvenuename],
		stg.[apuk_date],
		stg.[apuk_name],
		stg.[apuk_panelid],
		stg.[apuk_paneltype],
		stg.[apuk_tribunalchair],
		stg.[apuk_tribunalchair_entitytype],
		stg.[apuk_tribunalchairname],
		stg.[apuk_tribunalchairyominame],
		stg.[apuk_tribunallaymember],
		stg.[apuk_tribunallaymember_entitytype],
		stg.[apuk_tribunallaymembername],
		stg.[apuk_tribunallaymemberyominame],
		stg.[apuk_tribunallegalassessor],
		stg.[apuk_tribunallegalassessor_entitytype],
		stg.[apuk_tribunallegalassessorname],
		stg.[apuk_tribunallegalassessoryominame],
		stg.[apuk_tribunalmember],
		stg.[apuk_tribunalmember_entitytype],
		stg.[apuk_tribunalmembername],
		stg.[apuk_tribunalmemberyominame],
		stg.[apuk_tribunalvenue],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
